<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
import PageHeader from '@/Components/Shared/PageHeader.vue';
import { Button } from '@/components/ui/button';
const props=defineProps<{proposal:any}>();
const money=(v:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:props.proposal.currency||'USD'}).format((v||0)/100);
const setStatus=(status:string)=>router.post(`/admin/sponsorship-proposals/${props.proposal.id}/status`,{status});
</script>
<template><Head :title="proposal.title"/><div class="space-y-6 p-6"><div class="flex flex-wrap justify-between gap-3"><PageHeader :title="proposal.title" :description="`${proposal.proposal_number} · ${proposal.status}`"/><div class="flex gap-2"><Button v-if="proposal.status==='draft'" @click="setStatus('sent')">Mark Sent</Button><Button v-if="proposal.status==='sent'" @click="setStatus('accepted')">Accept Manually</Button><Button v-if="proposal.status==='accepted'&&!proposal.converted_at" @click="router.post(`/admin/sponsorship-proposals/${proposal.id}/convert`)">Convert</Button><Link v-if="!['accepted','converted'].includes(proposal.status)" :href="`/admin/sponsorship-proposals/${proposal.id}/edit`"><Button variant="outline">Edit</Button></Link></div></div><div class="grid gap-6 lg:grid-cols-3"><div class="space-y-6 lg:col-span-2"><section class="rounded-xl border p-5"><h2 class="font-semibold">Proposal Items</h2><div v-for="item in proposal.items" :key="item.id" class="flex justify-between border-b py-3"><div><div>{{item.description}}</div><div class="text-sm text-muted-foreground">{{item.placement?.name??'Custom'}} · {{item.quantity}} × {{money(item.unit_amount_cents)}}</div></div><strong>{{money(item.line_total_cents)}}</strong></div></section><section v-if="proposal.acceptance" class="rounded-xl border p-5"><h2 class="font-semibold">Electronic Acceptance</h2><dl class="mt-4 grid gap-3 sm:grid-cols-2"><div><dt class="text-sm text-muted-foreground">Signer</dt><dd>{{proposal.acceptance.signer_name}}<span v-if="proposal.acceptance.signer_title"> · {{proposal.acceptance.signer_title}}</span></dd></div><div><dt class="text-sm text-muted-foreground">Email</dt><dd>{{proposal.acceptance.signer_email}}</dd></div><div><dt class="text-sm text-muted-foreground">Accepted</dt><dd>{{proposal.acceptance.accepted_at}}</dd></div><div><dt class="text-sm text-muted-foreground">IP address</dt><dd>{{proposal.acceptance.ip_address||'Not recorded'}}</dd></div></dl></section><section class="rounded-xl border p-5"><h2 class="font-semibold">Status History</h2><div class="mt-3 divide-y"><div v-for="entry in proposal.status_history" :key="entry.id" class="py-3"><div class="flex justify-between gap-3"><p class="font-medium capitalize">{{entry.from_status||'Created'}} → {{entry.to_status}}</p><p class="text-sm text-muted-foreground">{{entry.created_at}}</p></div><p class="text-sm text-muted-foreground">{{entry.source}}<span v-if="entry.user"> · {{entry.user.name}}</span></p><p v-if="entry.reason" class="mt-1 text-sm">{{entry.reason}}</p></div></div></section></div><aside class="h-fit rounded-xl border p-5"><div>Subtotal <strong class="float-right">{{money(proposal.subtotal_cents)}}</strong></div><div>Discount <strong class="float-right">{{money(proposal.discount_cents)}}</strong></div><div class="mt-3 border-t pt-3 text-lg">Total <strong class="float-right">{{money(proposal.total_cents)}}</strong></div><div v-if="proposal.campaign" class="mt-5"><Link :href="`/admin/ad-campaigns/${proposal.campaign.id}`" class="underline">View Campaign</Link></div><div v-if="proposal.invoice"><Link :href="`/admin/advertising-invoices/${proposal.invoice.id}`" class="underline">View Invoice</Link></div></aside></div></div></template>
